(function(root){
const features=[
{id:'sso',name:'Enterprise SSO',category:'Enterprise readiness',effort:6,impact:9,confidence:85,alignment:10,signals:14,evidence:'E-01 · Synthetic discovery notes: 8 of 14 enterprise prospects requested SAML SSO. Two pilot customers described it as a procurement requirement. This is stated interest, not a signed purchase commitment.',assumption:'SSO will unlock enterprise conversions.',question:'Validate the procurement blocker with the two pilot customers. What else must be true before they buy?'},
{id:'ai',name:'AI Insights',category:'Intelligence & automation',effort:9,impact:8,confidence:45,alignment:7,signals:6,evidence:'E-02 · Synthetic interviews: 6 customers expressed interest in automated insights. No usability study or willingness-to-pay experiment has been completed. Effort excludes ongoing inference costs.',assumption:'Interest in AI will translate into repeat usage.',question:'Test a concierge prototype and measure repeat usage before committing nine capacity points.'},
{id:'analytics',name:'Analytics Dashboard',category:'Activation & engagement',effort:4,impact:7,confidence:75,alignment:8,signals:11,evidence:'E-03 · Synthetic support review: 11 accounts requested consolidated reporting. In a fictional usability study, 5 of 7 participants struggled to find existing usage metrics. Retention impact remains untested.',assumption:'Better reporting will improve retention.',question:'Define the activation or retention metric that would distinguish a successful dashboard from a frequently requested one.'},
{id:'mobile',name:'Mobile Experience',category:'Accessibility & reach',effort:7,impact:5,confidence:55,alignment:4,signals:8,evidence:'E-04 · Synthetic feedback: 8 customers requested mobile access. Illustrative analytics show 12% of sessions on mobile. The proposed scope includes responsive task management, not native apps.',assumption:'Mobile access is a priority for the enterprise segment.',question:'Segment the requests by buyer profile and identify the highest-value mobile task.'},
{id:'api',name:'Public API',category:'Platform & integrations',effort:5,impact:6,confidence:65,alignment:8,signals:9,evidence:'E-05 · Synthetic discovery: 9 accounts mentioned integration needs across 5 different systems. No endpoint specification or security review exists yet.',assumption:'A general-purpose API solves the requested integration needs.',question:'Identify the two most valuable integration workflows and review security and maintenance effort.'}
];
function score(f,goal){const alignment=goal==='enterprise'?f.alignment:goal==='engagement'?(f.id==='analytics'?10:f.id==='mobile'?8:5):(f.id==='ai'?10:f.id==='api'?9:5);return Math.round(((f.impact*.6+alignment*.4)*(f.confidence/100)/f.effort)*100)}
function assess(ids,capacity,goal){const selected=features.filter(f=>ids.includes(f.id));return{selected,effort:selected.reduce((n,f)=>n+f.effort,0),impact:selected.reduce((n,f)=>n+f.impact,0),confidence:selected.length?Math.round(selected.reduce((n,f)=>n+f.confidence,0)/selected.length):0,score:selected.reduce((n,f)=>n+score(f,goal),0),fits:selected.reduce((n,f)=>n+f.effort,0)<=capacity}}
function best(capacity,goal){let winner=assess([],capacity,goal);for(let mask=1;mask<1<<features.length;mask++){const candidate=assess(features.filter((f,i)=>mask&(1<<i)).map(f=>f.id),capacity,goal);if(candidate.fits&&candidate.score>winner.score)winner=candidate}return winner}
const api={features,score,assess,best};if(typeof module!=='undefined')module.exports=api;else root.DecisionEngine=api;
})(typeof window!=='undefined'?window:globalThis);
